// Push gate: decides whether the agent may send a push to a user right now.
// Rules, checked in this order (a blocked attempt is never counted as sent):
//   1. quiet hours, in the user's own time zone (window may cross midnight)
//   2. daily cap, counted per calendar day in the user's own time zone
// Invalid input fails closed: no push is allowed when we cannot tell it is safe.

const HISTORY_MS = 48 * 60 * 60 * 1000; // longer than any local day, so pruning is safe

const formatters = new Map();

function localParts(date, timeZone) {
  let fmt = formatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, fmt);
  }
  const p = {};
  for (const { type, value } of fmt.formatToParts(date)) p[type] = value;
  return {
    day: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseHHMM(s) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(typeof s === 'string' ? s.trim() : '');
  if (!m) return null;
  const h = Number(m[1]);
  const min = Number(m[2]);
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}

function inQuietHours(now, start, end) {
  if (start === end) return false; // empty window: no quiet period
  return start < end ? now >= start && now < end : now >= start || now < end;
}

export function createPushGate() {
  const sent = new Map(); // user id -> array of epoch ms of allowed pushes

  const deny = (reason) => ({ allowed: false, reason });

  return {
    attempt(user, now) {
      if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid_time');
      if (!user || (typeof user.id !== 'string' && typeof user.id !== 'number')) {
        return deny('invalid_user');
      }

      let local;
      try {
        local = localParts(now, user.timeZone);
      } catch {
        return deny('invalid_time_zone');
      }

      const start = parseHHMM(user.quietStart);
      const end = parseHHMM(user.quietEnd);
      if (start === null || end === null) return deny('invalid_quiet_hours');

      const cap = user.dailyCap;
      if (typeof cap !== 'number' || Number.isNaN(cap)) return deny('invalid_daily_cap');

      if (inQuietHours(local.minutes, start, end)) return deny('quiet_hours');

      const t = now.getTime();
      const history = (sent.get(user.id) ?? []).filter((x) => x > t - HISTORY_MS);
      const today = history.filter(
        (x) => localParts(new Date(x), user.timeZone).day === local.day,
      ).length;
      if (today >= cap) {
        sent.set(user.id, history);
        return deny('daily_cap_reached');
      }

      history.push(t);
      sent.set(user.id, history);
      return { allowed: true, reason: null };
    },
  };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/knock-g2-2/bot.mjs';

const tokyo = { id: 'u1', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();

// Tokyo = UTC+9. 23:00 JST = 14:00Z -> quiet; 06:59 JST = 21:59Z -> quiet; 07:00 JST = 22:00Z ok
assert.equal(g.attempt(tokyo, d('2026-03-10T14:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(tokyo, d('2026-03-10T21:59:00Z')).reason, 'quiet_hours');
assert.deepEqual(g.attempt(tokyo, d('2026-03-10T22:00:00Z')), { allowed: true, reason: null });
// 22:00 JST exactly = 13:00Z quiet
assert.equal(g.attempt(tokyo, d('2026-03-10T13:00:00Z')).reason, 'quiet_hours');

// Cap per local day: 3 on Mar 11 JST, 4th denied, blocked quiet attempts did not count
g = createPushGate();
for (const t of ['22:00', '23:00', '23:30']) assert.equal(g.attempt(tokyo, d(`2026-03-10T${t}:00Z`)).allowed, true); // 07:00,08:00,08:30 JST Mar 11
assert.equal(g.attempt(tokyo, d('2026-03-11T01:00:00Z')).reason, 'daily_cap_reached');
// next local day (Mar 12 JST 07:00 = Mar 11 22:00Z) resets, even though UTC day is same as before-midnight pushes
assert.equal(g.attempt(tokyo, d('2026-03-11T22:00:00Z')).allowed, true);

// Local midnight, not UTC midnight: LA user, 23:30 PDT-ish and 00:30 next local day are different days
const la = { id: 'u2', timeZone: 'America/Los_Angeles', quietStart: '00:00', quietEnd: '00:00', dailyCap: 1 };
g = createPushGate();
assert.equal(g.attempt(la, d('2026-07-01T06:30:00Z')).allowed, true); // Jun 30 23:30 PDT
assert.equal(g.attempt(la, d('2026-07-01T07:30:00Z')).allowed, true); // Jul 1 00:30 PDT, new day
assert.equal(g.attempt(la, d('2026-07-01T08:30:00Z')).reason, 'daily_cap_reached');

// Same-day window (no midnight cross) and per-call settings
const nap = { id: 'u3', timeZone: 'Europe/Istanbul', quietStart: '13:00', quietEnd: '15:00', dailyCap: 2 };
g = createPushGate();
assert.equal(g.attempt(nap, d('2026-01-01T10:30:00Z')).reason, 'quiet_hours'); // 13:30 +03
assert.equal(g.attempt(nap, d('2026-01-01T09:00:00Z')).allowed, true);
assert.equal(g.attempt({ ...nap, dailyCap: 1 }, d('2026-01-01T12:30:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt({ ...nap, dailyCap: 0 }, d('2026-01-02T09:00:00Z')).reason, 'daily_cap_reached');

// Independent gates and users
const g2 = createPushGate();
assert.equal(g2.attempt(nap, d('2026-01-01T09:00:00Z')).allowed, true);
assert.equal(g.attempt({ ...nap, id: 'other' }, d('2026-01-01T09:00:00Z')).allowed, true);

// DST day (US spring forward 2026-03-08): local day still one calendar day
const ny = { id: 'u4', timeZone: 'America/New_York', quietStart: '22:00', quietEnd: '07:00', dailyCap: 2 };
g = createPushGate();
assert.equal(g.attempt(ny, d('2026-03-08T05:30:00Z')).reason, 'quiet_hours'); // 00:30 EST
assert.equal(g.attempt(ny, d('2026-03-08T12:00:00Z')).allowed, true); // 08:00 EDT
assert.equal(g.attempt(ny, d('2026-03-09T03:30:00Z')).reason, 'quiet_hours'); // 23:30 EDT

// Bad input fails closed
assert.equal(g.attempt({ ...ny, timeZone: 'Mars/Base' }, d('2026-03-08T12:00:00Z')).reason, 'invalid_time_zone');
assert.equal(g.attempt({ ...ny, quietStart: 'x' }, d('2026-03-08T12:00:00Z')).reason, 'invalid_quiet_hours');
assert.equal(g.attempt(ny, new Date('nope')).reason, 'invalid_time');
console.log('all ok');
